// نقاط مضاعفة في أيام معينة + نقاط ثابتة لكل فاتورة (إعدادات لكل محل)
var McDaysAr = {Saturday:"السبت",Sunday:"الأحد",Monday:"الاثنين",Tuesday:"الثلاثاء",Wednesday:"الأربعاء",Thursday:"الخميس",Friday:"الجمعة"};
function McList(v){ if (Array.isArray(v)) return v.map(function(x){return String(x).trim();}).filter(Boolean);
  return String(v==null?"":v).split(",").map(function(x){return x.trim();}).filter(Boolean); }
function McMult(n){
  try {
    var days = McList(n && n.multiplier_days); if (!days.length) return 1;
    var m = Number(n && n.multiplier_value); if (!isFinite(m) || m <= 1) return 1;
    var en = new Intl.DateTimeFormat("en-US",{timeZone:"Africa/Cairo",weekday:"long"}).format(new Date());
    var ar = McDaysAr[en] || "";
    var hit = days.some(function(d){ return d === ar || d === en || d === "الإثنين" && ar === "الاثنين"; });
    return hit ? m : 1;
  } catch (e) { return 1; }
}
function McVisit(n){ var v = Number(n && n.visit_points); return isFinite(v) && v > 0 ? Math.floor(v) : 0; }
